style.css:
@-moz-document domain("google.com") {
/* --- Core Palette & Background --- */
    :root {
        --maxident-pink: #ff4a80;
        --maxident-hotpink: #e61f5b;
        --maxident-black: #0d0d0d;
        --maxident-darkgray: #1a1a1a;
        --maxident-lightgray: #2d2d2d;
        --maxident-white: #ffffff;
        --maxident-neon-green: #bfff00;
    }

    body, 
    .g, 
    #MainHTML {
        background-color: var(--maxident-black) !important;
        color: var(--maxident-white) !important;
    }

    /* --- Google Homepage Logo Modification --- */
    .lnX7b img, 
    .k1zZTe img,
    .logo img {
        filter: drop-shadow(0 0 8px var(--maxident-pink)) invert(1) hue-rotate(300deg) !important;
    }

    /* --- Search Bar Styling --- */
    .RNNXgb, 
    .SDkssb {
        background-color: var(--maxident-darkgray) !important;
        border: 2px solid var(--maxident-pink) !important;
        box-shadow: 0 0 15px rgba(255, 74, 128, 0.3) !important;
        border-radius: 24px !important;
    }

    .RNNXgb:hover, 
    .RNNXgb:focus-within {
        border-color: var(--maxident-neon-green) !important;
        box-shadow: 0 0 20px rgba(191, 255, 0, 0.5) !important;
    }

    /* Text inside search input */
    .gLFyf {
        color: var(--maxident-white) !important;
        font-family: 'Courier New', Courier, monospace, sans-serif !important;
        font-weight: bold !important;
    }

    /* --- Search Buttons & Interactive Elements --- */
    .FPdoLc input[type="submit"], 
    .gNO89b {
        background-color: var(--maxident-pink) !important;
        color: var(--maxident-black) !important;
        border: none !important;
        border-radius: 4px !important;
        font-weight: 900 !important;
        text-transform: uppercase !important;
        letter-spacing: 1px !important;
        transition: all 0.3s ease !important;
    }

    .FPdoLc input[type="submit"]:hover, 
    .gNO89b:hover {
        background-color: var(--maxident-neon-green) !important;
        color: var(--maxident-black) !important;
        transform: scale(1.05) !important;
        cursor: pointer !important;
    }

    /* --- Search Results Page Links & Text --- */
    /* Result Titles */
    .LC20lb, 
    .MBeuO, 
    h3 {
        color: var(--maxident-pink) !important;
        font-family: 'Arial Black', Gadget, sans-serif !important;
        text-shadow: 1px 1px 2px rgba(0,0,0,0.8) !important;
    }

    .LC20lb:hover {
        color: var(--maxident-neon-green) !important;
        text-decoration: underline !important;
    }

    /* Snippet/Description Text */
    .VwiC3b, 
    .MUwG0c, 
    .lyLwfc {
        color: #cccccc !important;
    }

    /* URL / Breadcrumb Text */
    .tjvca, 
    .byrY5, 
    cite {
        color: var(--maxident-neon-green) !important;
    }

    /* --- Header & Navigation Taps --- */
    .hdtb-mitem.hdtb-msel, 
    .Ymvw0b.active {
        color: var(--maxident-pink) !important;
        border-bottom: 3px solid var(--maxident-pink) !important;
    }

    .hdtb-mitem a, 
    .Ymvw0b {
        color: var(--maxident-white) !important;
    }

    /* --- Scrollbar Customization --- */
    ::-webkit-scrollbar {
        width: 10px !important;
    }

    ::-webkit-scrollbar-track {
        background: var(--maxident-black) !important;
    }

    ::-webkit-scrollbar-thumb {
        background: var(--maxident-pink) !important;
        border-radius: 5px !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: var(--maxident-neon-green) !important;
    }
}
